{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill would require every public school district (LEA) and public charter school in Tennessee to set aside one instructional day each school year to observe the Fourth of July. The bill says the Fourth of July falls in summer when school is out, so students should get special instruction during the school year. The director of schools or charter school director must choose the day each year. On that day, students in kindergarten through twelfth grade must receive age- and grade-appropriate instruction on the founding of the United States, the separation of the thirteen colonies from Great Britain, the Declaration of Independence, the U.S. Constitution, and the basic rights and freedoms of American citizens.",
      "rationale": "Conveys the responsible directors, annual designation of one instructional day, K–12 scope, age and grade appropriateness, and all required instructional subjects."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Each LEA and charter school would decide its own program and methods. Examples include interactive lessons, readings, writing assignments, discussions, or school assemblies. The instruction must meet grade-level goals.",
      "rationale": "Covers local determination of programs and methods, illustrative activities, and the requirement to meet grade-specific objectives."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "In grades K-5, students should be able to explain the meaning of the holiday, identify the U.S. as an independent nation, describe basic ideas of freedom and individual rights, and recognize national symbols.",
      "rationale": "Covers most K–5 objectives but omits understanding national symbols' connection to American freedom and independence."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "In grades 6-8, which may be taught through social studies, students should be able to describe the events leading to independence, explain why the colonies sought self-governance, summarize the purpose of the Declaration and the Constitution, and identify the principles of liberty, individual rights, limited government, and consent of the governed.",
      "rationale": "Conveys the grade range, optional social studies integration, and most objectives, but omits the requirement to summarize the significance, not just the purpose, of both founding documents."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "In grades 9-12, which may be taught through English language arts, students should be able to analyze the two documents as foundational texts, identify themes such as liberty, equality, and natural rights, evaluate the significance of American independence, and understand how founding principles connect to modern civic responsibilities.",
      "rationale": "Covers much of the high-school instruction but does not specify historical and philosophical evaluation, tie the listed themes to the American Revolution, or include the connection to American citizenship."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Directors must designate the day each year, ensure consistent implementation at each school, verify that the instruction meets the bill's requirements, and give guidance as needed.",
      "rationale": "Conveys directors' duties to ensure consistent school-level implementation and provide guidance as needed."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Directors must designate the day each year, ensure consistent implementation at each school, verify that the instruction meets the bill's requirements, and give guidance as needed. If the instruction is part of a social studies or English class, directors must verify it aligns with state academic standards set by the state board of education.",
      "rationale": "Covers directors' compliance verification duty and conditional alignment with state-board academic standards for social studies or English instruction."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The instruction must be nonpartisan and solely educational, focused on historical facts, the founding documents, and the civic principles behind them.",
      "rationale": "Conveys the nonpartisan, solely educational requirement and the prescribed historical, documentary, and civic focus."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Each LEA and charter school must periodically review its content, materials, and methods and update them as it sees fit, to follow best practices in civic education and keep class-based instruction aligned with state standards.",
      "rationale": "Covers periodic review, discretionary updates, and both purposes. In context, class-based instruction and state standards refer to the preceding discussion of social studies or English classes and state-board standards."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill takes effect when it becomes law and applies starting with the 2026-2027 school year.",
      "rationale": "Conveys immediate effectiveness upon becoming law and ongoing application beginning in the specified school year."
    }
  ]
}
